CREATE SCHEMA IF NOT EXISTS pis;
CREATE TABLE IF NOT EXISTS pis.audit_event (id UUID PRIMARY KEY, operation_code VARCHAR(64) NOT NULL, permission_code VARCHAR(64) NOT NULL, actor_ref VARCHAR(128) NOT NULL, subject_type_code VARCHAR(32) NOT NULL, target_object_id UUID, target_object_kind_code VARCHAR(32), authorization_outcome VARCHAR(32) NOT NULL, processing_outcome VARCHAR(32) NOT NULL, correlation_id VARCHAR(128) NOT NULL, reason VARCHAR(500), category_code VARCHAR(32), changes_json TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS pis.outbox_event (id UUID PRIMARY KEY, event_identity VARCHAR(128) NOT NULL UNIQUE, event_type_code VARCHAR(128) NOT NULL, subject_id UUID NOT NULL, subject_kind_code VARCHAR(64) NOT NULL, aggregate_version BIGINT NOT NULL, correlation_id VARCHAR(128) NOT NULL, payload_digest VARCHAR(128) NOT NULL, publish_state_code VARCHAR(32) NOT NULL, occurred_at TIMESTAMP WITH TIME ZONE NOT NULL, created_by_ref VARCHAR(128) NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_diagnosis_task (id UUID PRIMARY KEY, task_no VARCHAR(64) NOT NULL, case_id UUID NOT NULL, pathology_modality_code VARCHAR(32) NOT NULL, task_category_code VARCHAR(32) NOT NULL, priority_code VARCHAR(32) NOT NULL, task_state_code VARCHAR(40) NOT NULL, assigned_actor_ref VARCHAR(128), responsible_actor_ref VARCHAR(128), represented_actor_ref VARCHAR(128), organization_reference VARCHAR(128) NOT NULL, data_scope_code VARCHAR(64) NOT NULL, concurrency_version BIGINT NOT NULL, started_at TIMESTAMP WITH TIME ZONE, completed_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL, created_by_ref VARCHAR(128) NOT NULL, UNIQUE(organization_reference, task_no));
CREATE TABLE IF NOT EXISTS pis.p19_diagnosis_responsibility_history (id UUID PRIMARY KEY, task_id UUID NOT NULL, from_actor_ref VARCHAR(128), to_actor_ref VARCHAR(128), action_code VARCHAR(40) NOT NULL, reason_text VARCHAR(1000), occurred_at TIMESTAMP WITH TIME ZONE NOT NULL, recorded_by_ref VARCHAR(128) NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_diagnosis_work_draft (id UUID PRIMARY KEY, task_id UUID NOT NULL UNIQUE, owner_actor_ref VARCHAR(128) NOT NULL, gross_description_reference VARCHAR(128), microscopic_description TEXT, diagnosis_conclusion TEXT, supplementary_note TEXT, structured_items TEXT, terminology_reference VARCHAR(128), concurrency_version BIGINT NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_by_ref VARCHAR(128) NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_diagnosis_opinion (id UUID PRIMARY KEY, task_id UUID NOT NULL, case_id UUID NOT NULL, diagnosis_type_code VARCHAR(32) NOT NULL, opinion_state_code VARCHAR(32) NOT NULL, current_version_no INTEGER NOT NULL, current_version_id UUID, created_at TIMESTAMP WITH TIME ZONE NOT NULL, created_by_ref VARCHAR(128) NOT NULL, UNIQUE(task_id, diagnosis_type_code));
CREATE TABLE IF NOT EXISTS pis.p19_diagnosis_opinion_version (id UUID PRIMARY KEY, opinion_id UUID NOT NULL, version_no INTEGER NOT NULL, version_state_code VARCHAR(32) NOT NULL, gross_description_reference VARCHAR(128), microscopic_description TEXT NOT NULL, diagnosis_conclusion TEXT NOT NULL, supplementary_note TEXT, structured_items TEXT, terminology_reference VARCHAR(128), evidence_version_summary TEXT NOT NULL, submitted_by_ref VARCHAR(128) NOT NULL, submitted_at TIMESTAMP WITH TIME ZONE NOT NULL, prior_version_id UUID, UNIQUE(opinion_id, version_no));
CREATE TABLE IF NOT EXISTS pis.p19_diagnosis_follow_up (id UUID PRIMARY KEY, task_id UUID NOT NULL, target_opinion_version_id UUID NOT NULL, follow_up_actor_ref VARCHAR(128) NOT NULL, follow_up_opinion TEXT NOT NULL, consistency_code VARCHAR(32) NOT NULL, return_reason TEXT, adoption_recommendation TEXT, follow_up_state_code VARCHAR(32) NOT NULL, version_no INTEGER NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, created_by_ref VARCHAR(128) NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_diagnosis_review (id UUID PRIMARY KEY, target_opinion_version_id UUID, target_report_content_version_id UUID, review_kind_code VARCHAR(32) NOT NULL, decision_code VARCHAR(32) NOT NULL, reviewer_actor_ref VARCHAR(128) NOT NULL, review_reason VARCHAR(2000), reviewed_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_report (id UUID PRIMARY KEY, report_no VARCHAR(64) NOT NULL, case_id UUID NOT NULL, report_type_code VARCHAR(32) NOT NULL, report_state_code VARCHAR(32) NOT NULL, current_effective_version_id UUID, next_version_no INTEGER NOT NULL, concurrency_version BIGINT NOT NULL, organization_reference VARCHAR(128) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, created_by_ref VARCHAR(128) NOT NULL, UNIQUE(organization_reference, report_no));
CREATE TABLE IF NOT EXISTS pis.p19_report_draft (id UUID PRIMARY KEY, report_id UUID NOT NULL UNIQUE, owner_actor_ref VARCHAR(128) NOT NULL, clinical_information TEXT, specimen_information TEXT, gross_description TEXT, microscopic_description TEXT, diagnosis_conclusion TEXT NOT NULL, supplementary_note TEXT, technical_result_reference_summary TEXT, concurrency_version BIGINT NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_by_ref VARCHAR(128) NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_report_content_version (id UUID PRIMARY KEY, report_id UUID NOT NULL, version_no INTEGER NOT NULL, content_state_code VARCHAR(32) NOT NULL, patient_snapshot TEXT NOT NULL, encounter_snapshot TEXT NOT NULL, case_no_snapshot VARCHAR(128) NOT NULL, specimen_material_summary TEXT NOT NULL, clinical_information TEXT, specimen_information TEXT, gross_description TEXT, microscopic_description TEXT, diagnosis_conclusion TEXT NOT NULL, supplementary_note TEXT, technical_result_reference_summary TEXT, diagnosis_version_id UUID NOT NULL, template_logic_version VARCHAR(64) NOT NULL, formed_by_ref VARCHAR(128) NOT NULL, formed_at TIMESTAMP WITH TIME ZONE NOT NULL, prior_version_id UUID, UNIQUE(report_id, version_no));
CREATE TABLE IF NOT EXISTS pis.p19_report_section_version (id UUID PRIMARY KEY, report_content_version_id UUID NOT NULL, section_code VARCHAR(48) NOT NULL, body_text TEXT NOT NULL, source_code VARCHAR(32) NOT NULL, adopted_state_code VARCHAR(32) NOT NULL, formed_by_ref VARCHAR(128) NOT NULL, formed_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(report_content_version_id, section_code));
CREATE TABLE IF NOT EXISTS pis.p19_signing_fact (id UUID PRIMARY KEY, report_id UUID NOT NULL, report_content_version_id UUID NOT NULL UNIQUE, signing_actor_ref VARCHAR(128) NOT NULL, actual_operator_ref VARCHAR(128) NOT NULL, responsible_actor_ref VARCHAR(128) NOT NULL, signed_at TIMESTAMP WITH TIME ZONE NOT NULL, enhanced_authentication_reference VARCHAR(128) NOT NULL, second_review_reference UUID NOT NULL, task_responsibility_snapshot VARCHAR(128) NOT NULL, signed_object_version BIGINT NOT NULL, signing_result_code VARCHAR(32) NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_report_revision_relation (id UUID PRIMARY KEY, report_id UUID NOT NULL, original_version_id UUID NOT NULL, replacement_version_id UUID, relation_type_code VARCHAR(32) NOT NULL, reason_text VARCHAR(2000) NOT NULL, current_effective_flag BOOLEAN NOT NULL, formed_by_ref VARCHAR(128) NOT NULL, formed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_report_supplement (id UUID PRIMARY KEY, report_id UUID NOT NULL, original_version_id UUID NOT NULL, supplement_version_id UUID, reason_text VARCHAR(2000) NOT NULL, request_state_code VARCHAR(32) NOT NULL, requested_by_ref VARCHAR(128) NOT NULL, requested_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_report_correction (id UUID PRIMARY KEY, report_id UUID NOT NULL, original_version_id UUID NOT NULL, correction_version_id UUID, error_type_code VARCHAR(64) NOT NULL, reason_text VARCHAR(2000) NOT NULL, request_state_code VARCHAR(32) NOT NULL, requested_by_ref VARCHAR(128) NOT NULL, requested_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_report_withdrawal_request (id UUID PRIMARY KEY, report_id UUID NOT NULL, original_version_id UUID NOT NULL, reason_text VARCHAR(2000) NOT NULL, request_state_code VARCHAR(32) NOT NULL, requested_by_ref VARCHAR(128) NOT NULL, requested_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_report_withdrawal_fact (id UUID PRIMARY KEY, withdrawal_request_id UUID NOT NULL UNIQUE, report_id UUID NOT NULL, original_version_id UUID NOT NULL, approved_by_ref VARCHAR(128) NOT NULL, executed_by_ref VARCHAR(128) NOT NULL, reason_text VARCHAR(2000) NOT NULL, executed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_report_resign_relation (id UUID PRIMARY KEY, report_id UUID NOT NULL, prior_signing_fact_id UUID NOT NULL, new_signing_fact_id UUID NOT NULL, formed_by_ref VARCHAR(128) NOT NULL, formed_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_report_result_reference (id UUID PRIMARY KEY, report_id UUID NOT NULL, report_content_version_id UUID NOT NULL, technical_project_id UUID, result_identity VARCHAR(128) NOT NULL, result_version_reference VARCHAR(128) NOT NULL, result_digest VARCHAR(128) NOT NULL, adoption_state_code VARCHAR(32) NOT NULL, recorded_by_ref VARCHAR(128) NOT NULL, recorded_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_state_history (id UUID PRIMARY KEY, target_object_id UUID NOT NULL, target_object_kind_code VARCHAR(48) NOT NULL, source_state_code VARCHAR(48), target_state_code VARCHAR(48) NOT NULL, transition_event_code VARCHAR(64) NOT NULL, expected_version BIGINT, resulting_version BIGINT NOT NULL, reason_text VARCHAR(1000), occurred_at TIMESTAMP WITH TIME ZONE NOT NULL, recorded_by_ref VARCHAR(128) NOT NULL);
CREATE TABLE IF NOT EXISTS pis.p19_command_idempotency (id UUID PRIMARY KEY, operation_code VARCHAR(64) NOT NULL, idempotency_key VARCHAR(160) NOT NULL, payload_digest VARCHAR(128) NOT NULL, result_object_id UUID NOT NULL, actor_ref VARCHAR(128) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, UNIQUE(operation_code, idempotency_key));
